import {balanceCases,balancePages} from './balance-stall-content.mjs';
import {balanceView,startBalance,resumeBalance,setBalancePage,addBalanceSupport,chooseBalanceMass,resetBalance,changeBalance,checkBalance,balanceCheckMatches,balanceModel,balanceChange} from './balance-stall-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const relationText=r=>r==='equal'?'Both pans have the same model mass; the balance is level.':r==='left'?'The left pan is heavier and lower.':'The right pan is heavier and lower.';
const massLabel=n=>`${n} model mass ${n===1?'unit':'units'}`;
const sideName=s=>s==='both'?'both pans':`the ${s} pan`;
function expression(source,groups,side,reveal){const loose=source.kind==='parcel'?groups.filter(n=>n!==0):groups,parts=loose.length?loose.map(String):[];if(source.parcelSide===side)parts.unshift(reveal?`parcel (${source.parcelMass})`:'parcel');return parts.join(' + ')||'0';}
function expressions(source,live,relation,reveal,recorded=false){return `<div class="balance-expressions" aria-label="${recorded?'Recorded':'Current'} relationship"><span><strong>Left</strong><span>${esc(expression(source,live.left,'left',reveal))}</span></span><strong class="balance-relation" aria-label="${relation==='equal'?'equals':relation==='left'?'greater than':'less than'}">${relation==='equal'?'=':relation==='left'?'&gt;':'&lt;'}</strong><span><strong>Right</strong><span>${esc(expression(source,live.right,'right',reveal))}</span></span></div><p class="balance-relation-text">${recorded?'Recorded relation: ':''}${relationText(relation)}</p>`;}
function apparatus(source,live,relation,reveal=false,recorded=false){const offset=relation==='equal'?0:relation==='left'?20:-20,leftY=270+offset,rightY=270-offset,description=`${recorded?'Recorded teaching apparatus.':'Current teaching apparatus.'} Left loose groups: ${live.left.join(' and ')}${source.parcelSide==='left'?', plus the whole sealed parcel':''}. Right loose groups: ${live.right.join(' and ')}${source.parcelSide==='right'?', plus the whole sealed parcel':''}. ${relationText(relation)} Each small weight is one model mass unit. The parcel is not one unit just because it is one object.`;return `<figure class="balance-apparatus"><div class="balance-scene" role="img" aria-label="${esc(description)}" data-balance-relation="${relation}"><svg viewBox="0 0 320 320" aria-hidden="true" focusable="false"><path d="M160 155L133 303H187Z" fill="#cfbc8f" stroke="#183f39" stroke-width="3"/><path d="M110 310H210" stroke="#183f39" stroke-width="5" stroke-linecap="round"/><path d="M70 ${155+offset}L250 ${155-offset}" stroke="#183f39" stroke-width="6" stroke-linecap="round"/><circle cx="160" cy="155" r="8" fill="#e9b84a" stroke="#183f39" stroke-width="2"/>${[['left',70,leftY,155+offset],['right',250,rightY,155-offset]].map(([side,x,y,beam])=>`<g data-balance-pan-art="${side}"><path d="M${x} ${beam+4}L${x-60} ${y}M${x} ${beam+4}L${x+60} ${y}" fill="none" stroke="#829686" stroke-width="2"/><path d="M${x-60} ${y}Q${x} ${y+19} ${x+60} ${y}" fill="#e3e9dc" stroke="#183f39" stroke-width="3"/></g>`).join('')}</svg>${['left','right'].map(side=>`<div class="balance-pan balance-pan-${side}" data-balance-pan="${side}" style="bottom:${(320-(side==='left'?leftY:rightY))/320*100}%" aria-hidden="true">${source.parcelSide===side?`<div class="balance-parcel"><strong>${reveal?source.parcelMass:'?'}</strong><span>parcel</span></div>`:''}<div class="balance-unit-groups">${live[side].map((n,i)=>`<div class="balance-unit-group" data-balance-group="${side}-${i}"><div class="balance-units">${Array.from({length:n},()=>'<span class="balance-unit">1</span>').join('')}</div><span class="balance-group-count">${n}</span></div>`).join('')}</div></div>`).join('')}</div><figcaption>Equal arms and matched pans. Each small weight is one model mass unit; its group count is below it. Positions do not change mass.</figcaption></figure>`;}
function evidenceText(e){return `<ul class="balance-evidence"><li>Paired addition from a level state tried: ${e.pairedAdd?'yes':'no'}.</li><li>Paired removal from a level state tried: ${e.pairedRemove?'yes':'no'}.</li><li>A one-sided change tried: ${e.oneSided?'yes':'no'}.</li></ul>`;}
function controls(r){return `<fieldset class="balance-step-controls"><legend>Change one loose unit at a time</legend><div class="balance-six-controls">${['left','both','right'].map(side=>`<section><h3>${side==='both'?'Both':side==='left'?'Left':'Right'}</h3>${[1,-1].map(delta=>{const result=balanceChange(r.source,r.live,side,delta);return button(`data-balance-change="${side}" data-delta="${delta}" aria-label="${delta===1?'Add':'Remove'} one unit ${delta===1?'to':'from'} ${sideName(side)}"${result.ok?'':' disabled'}`,delta===1?'Add 1':'Remove 1');}).join('')}</section>`).join('')}</div>${balanceChange(r.source,r.live,'both',-1).ok?'':`<p class="tiny balance-move-boundary">Paired removal needs a loose unit on each pan. ${r.source.kind==='parcel'?'The parcel stays whole; its mass does not make it a loose unit.':'An empty pan has no unit to remove.'}</p>`}${balanceChange(r.source,r.live,'both',1).ok?'':'<p class="tiny balance-move-boundary">Each pan holds at most 20 loose units. Paired addition waits until both have room; neither pan changes alone.</p>'}</fieldset>`;}
function proposal(r){return r.source.kind==='parcel'?`<label for="balance-proposal"><strong>My idea for the whole parcel</strong></label><select id="balance-proposal"><option value=""${r.proposal===null?' selected':''}>Leave my idea blank</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}"${r.proposal===i+1?' selected':''}>${massLabel(i+1)}</option>`).join('')}</select><p class="tiny">Wrapping is included. An idea never changes the balance’s fixed parcel mass.</p>`:'';}
function livePage(r){const model=balanceModel(r.source,r.live),reveal=r.support.includes('reveal');return `<h2 id="balance-prompt" tabindex="-1">${esc(r.source.question)}</h2><div class="balance-live-layout"><section class="balance-picture" aria-label="Current apparatus">${apparatus(r.source,r.live,model.relation,reveal)}${expressions(r.source,r.live,model.relation,reveal)}</section><section class="balance-actions" aria-label="Try a change">${controls(r)}<p class="balance-last-action">${r.lastAction?esc(r.lastAction.feedback):r.source.kind==='parcel'?'Try one change, then notice the relation. The sealed parcel stays on its pan.':'Try one change, then notice whether the two arrangements still have the same mass.'}</p>${proposal(r)}${button('data-balance-check',r.source.kind==='parcel'?'Check / keep this idea':'Keep this balance',true)}<p class="tiny">An idea may stay blank. The latest 8 checks stay here; keeping a ninth removes the oldest check.</p>${button('data-balance-reset','Return to the starting arrangement')}<p class="tiny">Reset clears this idea and the current action flags. It keeps support and all earlier checks.</p></section></div>`;}
function checkRecord(r,c,index,notes=false){const reveal=c.input.support.includes('reveal'),parcel=c.source.kind==='parcel';return `<section class="balance-record" tabindex="-1"><h3>${index===r.checks.length-1&&balanceCheckMatches(r,c)?'Latest check of these inputs':'Earlier recorded check'}</h3><p class="balance-feedback">${esc(c.feedback)}</p><p><strong>Recorded relation:</strong> ${relationText(c.relation)}</p>${parcel?`<p><strong>Recorded whole-parcel idea:</strong> ${c.input.proposal===null?'left blank':massLabel(c.input.proposal)}.<br><strong>Recorded value match:</strong> ${c.valueMatch===null?'unobserved':c.valueMatch?'yes':'no'}.<br><strong>Recorded parcel isolated on a level balance:</strong> ${c.isolated===null?'not recorded':c.isolated?'yes':'no'}.</p>`:''}${evidenceText(c.input.evidence)}<p class="tiny">These descriptive actions do not establish how the idea was found. Recorded support: ${esc(c.input.support.join(', ')||'none recorded')}.</p><details class="balance-frozen"><summary>Apparatus and source kept with this check</summary><h4>${esc(c.source.title)}</h4><p>${esc(c.source.question)}</p>${apparatus(c.source,c.input.live,c.relation,reveal,true)}${expressions(c.source,c.input.live,c.relation,reveal,true)}<p><strong>Recorded totals:</strong> ${['left','right'].map(side=>`${side==='left'?'Left':'Right'}: ${parcel&&c.source.parcelSide===side&&!reveal&&!notes?'parcel total hidden with the unrevealed mass':massLabel(c.totals[side])}`).join('; ')}.</p>${c.input.lastAction?`<p><strong>Recorded last action:</strong> ${esc(c.input.lastAction.feedback)}</p>`:''}<p>${esc(c.source.help)}</p></details></section>`;}
function keptPage(r){const latest=r.checks.at(-1);return `<h2 id="balance-prompt" tabindex="-1">Our kept balance checks</h2>${latest?checkRecord(r,latest,r.checks.length-1):'<p>No check has been kept yet. Your current arrangement and idea are waiting.</p>'}${button('data-balance-page="balance"','Change the same balance',true)}${r.checks.length>1?`<details><summary>Earlier checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkRecord(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="balance-catalog"><h2>Choose a balance case</h2><p>All eight cases are open. Choose one, then explicitly start a visit.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="balance-start-form"><label for="balance-case">Case</label><select id="balance-case" name="case">${balanceCases.map(source=>`<option value="${source.id}"${v.current?.source.id===source.id?' selected':''}>${esc(source.title)}</option>`).join('')}</select><button class="secondary" type="submit">Start this case</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-balance-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function balanceStallPage(state){const v=balanceView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a><h1>The Balance Stall</h1><p>The market crew is checking parcel labels. What can change while two pans keep the same mass?</p></header>`;if(v.status==='unavailable')return `<div class="balance-page">${heading}<section class="balance-sheet"><h2>Earlier work is safe</h2><p>This saved stall uses a format we cannot continue here. It remains unchanged; the Workshop is open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.balanceStall,null,2))}</pre></details></section></div>`;return `<div class="balance-page">${heading}<section class="balance-sheet"><nav class="balance-tabs" aria-label="Balance Stall pages">${balancePages.map(p=>button(`data-balance-page="${p}" aria-current="${v.page===p?'page':'false'}"`,p==='balance'?'Balance':'Kept checks',v.page===p)).join('')}</nav>${r?`<p class="balance-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Familiar practice':''}</p>`:''}<p id="balance-status" class="balance-status" role="status" tabindex="-1"></p>${r?v.page==='kept'?keptPage(r):livePage(r):`<h2 id="balance-prompt" tabindex="-1">Open a market balance</h2><p>Practice model mass with identical loose units and a sealed whole parcel. These are supplied results, not physical measurements.</p>${catalog(v)}`}${r?`<details id="balance-help" data-round="${r.id}"><summary>Help us think about same mass</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear this help')}${button('data-balance-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}${r.source.kind==='parcel'?`<p>Mass help reveals the model mass of this whole parcel, wrapping included, and is recorded as support.</p>${button('data-balance-reveal',r.support.includes('reveal')?'Parcel mass help is open':'Show the parcel’s model mass')}${r.support.includes('reveal')?`<p class="balance-revealed">This whole sealed parcel has ${massLabel(r.source.parcelMass)}.</p>`:''}`:''}</details><details><summary>Choose another case</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function balanceStallNotes(state){const v=balanceView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Balance Stall · earlier format</summary><pre>${esc(JSON.stringify(state.balanceStall,null,2))}</pre></details>`;return `<details class="panel balance-page"><summary>Balance Stall (${v.rounds.length} visits)</summary><p>Supplied ideal model mass, not physical measurement or general equation attainment. Proposed value, isolation, descriptive action evidence and support are separate. No independent method is inferred. Full frozen sources and raw recorded totals remain in the notes download.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Familiar: ${r.familiar?'yes':'no'}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p><p>Current loose groups: left ${r.live.left.join(' + ')}, right ${r.live.right.join(' + ')}. Current idea: ${r.proposal===null?'blank':massLabel(r.proposal)}.</p>${evidenceText(r.evidence)}<details><summary>Frozen model source for grown-ups</summary><pre>${esc(JSON.stringify(r.source,null,2))}</pre></details>${r.checks.map((c,i)=>checkRecord(r,c,i,true)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindBalanceStall(state,{save,render,focus}){
 const boundId=balanceView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&balanceView(state).current?.id===boundId;
 const show=(message='',target='#balance-prompt')=>{const id=balanceView(state).current?.id,open=[...document.querySelectorAll('.balance-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(balanceView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#balance-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 document.querySelector('#balance-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||balanceView(state).current?.id!==boundId)return;const r=startBalance(state,new FormData(form).get('case'));show(r?'A new balance visit is ready. Earlier checks stay in their visits.':'A new visit cannot be created because its saved visit numbers have reached the supported limit. Existing work remains available.',r?'#balance-prompt':'#balance-status');});
 document.querySelectorAll('[data-balance-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||balanceView(state).current?.id!==boundId)return;const ok=resumeBalance(state,Number(b.dataset.balanceResume));show(ok?'Earlier visit opened. Its checks remain unchanged.':'That visit could not be opened.');}));
 bind('[data-balance-page]',b=>{setBalancePage(state,b.dataset.balancePage);show();});
 bind('[data-balance-change]',b=>{const side=b.dataset.balanceChange,delta=Number(b.dataset.delta),result=changeBalance(state,side,delta),r=balanceView(state).current,available=r&&balanceChange(r.source,r.live,side,delta).ok;show(result?.feedback||'The arrangement did not change.',`[data-balance-change="${side}"][data-delta="${available?delta:-delta}"]`);});
 document.querySelector('#balance-proposal')?.addEventListener('change',e=>{const select=e.currentTarget;if(!sameVisit(select))return;chooseBalanceMass(state,select.value===''?null:Number(select.value));show('Your idea changed. The parcel and apparatus still use the same fixed model mass.','#balance-proposal');});
 bind('[data-balance-reset]',()=>{resetBalance(state);show('Starting arrangement restored; idea and action flags cleared. Earlier checks and support remain.','[data-balance-reset]');});
 bind('[data-balance-check]',()=>{const c=checkBalance(state);if(c)setBalancePage(state,'kept');show(c?'This check is kept with separate value, isolation and action records.':'This check could not be kept.',c?'.balance-record':'#balance-status');});
 bind('[data-balance-together]',()=>{addBalanceSupport(state,'together');show('Thinking together recorded as support.','[data-balance-together]');});
 bind('[data-balance-reveal]',()=>{addBalanceSupport(state,'reveal');show(`Mass help: this whole sealed parcel has ${massLabel(balanceView(state).current.source.parcelMass)}.`,'[data-balance-reveal]');});
 const help=document.querySelector('#balance-help');help?.addEventListener('toggle',()=>{if(help.open&&sameVisit(help)&&Number(help.dataset.round)===boundId){addBalanceSupport(state,'help');save();}});
 document.querySelectorAll('.balance-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b)){addBalanceSupport(state,'audio');save();}}));
}
